descriptor.templateCss:
.pcs-card-container {
  box-sizing: border-box;
  width: 100%;
  height: 100%;
  background: linear-gradient(160deg, rgba(14, 25, 16, 0.95) 0%, rgba(8, 15, 9, 0.98) 100%);
  border-radius: 14px;
  border: 1px solid rgba(100, 184, 86, 0.22);
  border-top: 3.5px solid #38bdf8;
  padding: 16px 20px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.45);
}
.pcs-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.pcs-title {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.6px;
  color: #94a3b8;
}
.pcs-icon { font-size: 16px; }
.pcs-badge {
  font-size: 11px;
  font-weight: 700;
  color: #38bdf8;
  border: 1.5px solid #38bdf8;
  background: rgba(56, 189, 248, 0.12);
  padding: 2px 10px;
  border-radius: 20px;
}
.pcs-main-metric {
  display: flex;
  align-items: baseline;
  gap: 8px;
  margin: 4px 0;
}
.main-num {
  font-size: 34px;
  font-weight: 800;
  color: #38bdf8;
  line-height: 1;
}
.main-unit {
  font-size: 16px;
  font-weight: 600;
  color: #94a3b8;
}
.pcs-breakdown-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin: 4px 0;
}
.pcs-row {
  display: flex;
  flex-direction: column;
  gap: 3px;
}
.row-info {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
}
.pcs-tag { color: #cbd5e1; font-weight: 500; }
.pcs-val { color: #38bdf8; font-weight: 700; }
.bar-track {
  width: 100%;
  height: 6px;
  background: rgba(255, 255, 255, 0.08);
  border-radius: 4px;
  overflow: hidden;
}
.bar-fill {
  height: 100%;
  border-radius: 4px;
  background: linear-gradient(90deg, #38bdf8, #64B856);
  transition: width 0.4s ease;
}
.pcs-footer {
  display: flex;
  justify-content: space-between;
  font-size: 11px;
  color: #64748b;
  border-top: 1px solid rgba(148, 163, 184, 0.12);
  padding-top: 8px;
  margin-top: 4px;
}

descriptor.controllerScript:
self.onInit = function() { self.onDataUpdated(); };
self.onDataUpdated = function() {
  var data = self.ctx.data;
  var p1 = 15.0, p2 = 14.9, p3 = 14.9;
  var nominalMax = 250.0;

  if (data && data.length > 0) {
    for (var i = 0; i < data.length; i++) {
      var item = data[i];
      if (item.data && item.data.length > 0) {
        var v = parseFloat(item.data[item.data.length - 1][1]);
        var k = (item.dataKey.label || item.dataKey.name || "").toLowerCase();
        if (!isNaN(v)) {
          if (k.indexOf('pcs1') !== -1 || i === 0) p1 = v;
          else if (k.indexOf('pcs2') !== -1 || i === 1) p2 = v;
          else if (k.indexOf('pcs3') !== -1 || i === 2) p3 = v;
        }
      }
    }
  }

  var total = p1 + p2 + p3;
  var maxVal = Math.max(p1, p2, p3, nominalMax, 1);
  var container = self.ctx.$container ? self.ctx.$container[0] : null;
  if (container) {
    var elTot = container.querySelector('#pac-total-val');
    if (elTot) elTot.textContent = total.toFixed(1);

    var setRow = function(idVal, idBar, val) {
      var ev = container.querySelector(idVal);
      var eb = container.querySelector(idBar);
      if (ev) ev.textContent = val.toFixed(1) + ' kW';
      if (eb) eb.style.width = Math.min(100, Math.max(0, (val / maxVal) * 100)) + '%';
    };
    setRow('#pac-pcs1-val', '#pac-pcs1-bar', p1);
    setRow('#pac-pcs2-val', '#pac-pcs2-bar', p2);
    setRow('#pac-pcs3-val', '#pac-pcs3-bar', p3);
  }
};
self.onDestroy = function() {};
